// Portable, end-to-end encrypted backup contract (P02 decisions 3 and 4).
// The backup contains envelopes whose DEKs are re-wrapped under a key derived from the user's
// recovery key. Payload ciphertext is carried unchanged. No server, no cloud, no XRAI-held key.

/// 256-bit user recovery key. Generated by the adapter from the system CSPRNG; shown to the user
/// once; never stored by XRAI. Its description is redacted.
public struct RecoveryKey: Hashable, Sendable {
    public static let byteCount = 32
    public let bytes: [UInt8]

    public init(bytes: [UInt8]) throws {
        guard bytes.count == RecoveryKey.byteCount else {
            throw VaultError.recoveryKeyInvalid(reason: "expected \(RecoveryKey.byteCount) bytes, got \(bytes.count)")
        }
        // Reject the all-zero key as an obvious failure of the random source.
        guard bytes.contains(where: { $0 != 0 }) else { throw VaultError.recoveryKeyInvalid(reason: "all-zero key") }
        self.bytes = bytes
    }

    /// Hex in groups of 8 characters for human transcription. Display only.
    public var displayGroups: [String] {
        let hex = bytes.map { b -> String in
            let s = String(b, radix: 16)
            return s.count == 1 ? "0" + s : s
        }.joined()
        var out: [String] = []
        var i = hex.startIndex
        while i < hex.endIndex {
            let j = hex.index(i, offsetBy: 8, limitedBy: hex.endIndex) ?? hex.endIndex
            out.append(String(hex[i..<j]))
            i = j
        }
        return out
    }

    /// Parses the grouped hex form (spaces/dashes ignored).
    public static func parse(display: String) throws -> RecoveryKey {
        let cleaned = display.filter { $0 != " " && $0 != "-" }.lowercased()
        guard cleaned.count == RecoveryKey.byteCount * 2 else {
            throw VaultError.recoveryKeyInvalid(reason: "wrong length")
        }
        var out: [UInt8] = []
        var chars = Array(cleaned)
        while !chars.isEmpty {
            let pair = String(chars[0...1])
            chars.removeFirst(2)
            guard let v = UInt8(pair, radix: 16) else { throw VaultError.recoveryKeyInvalid(reason: "non-hex character") }
            out.append(v)
        }
        return try RecoveryKey(bytes: out)
    }
}

extension RecoveryKey: CustomStringConvertible, CustomDebugStringConvertible {
    public var description: String { "RecoveryKey(redacted)" }
    public var debugDescription: String { "RecoveryKey(redacted)" }
}

/// The portable backup: versioned, salted, MAC-protected container of envelopes.
public struct PortableBackup: Hashable, Sendable {
    public static let magic: [UInt8] = Array("XRAIBK".utf8)
    public static let currentFormatVersion: UInt16 = 1
    public static let backupKeyID = "backup"

    public let formatVersion: UInt16
    public let salt: [UInt8]
    public let createdAtUnixSeconds: Int64
    public let entries: [RecordEnvelope]
    /// HMAC over everything above (adapter computes it with a key derived from the recovery key).
    public let integrityTag: [UInt8]

    public init(formatVersion: UInt16 = PortableBackup.currentFormatVersion, salt: [UInt8], createdAtUnixSeconds: Int64, entries: [RecordEnvelope], integrityTag: [UInt8]) {
        self.formatVersion = formatVersion
        self.salt = salt
        self.createdAtUnixSeconds = createdAtUnixSeconds
        self.entries = entries
        self.integrityTag = integrityTag
    }

    /// Bytes covered by the integrity tag.
    public static func authenticatedBytes(formatVersion: UInt16, salt: [UInt8], createdAtUnixSeconds: Int64, entries: [RecordEnvelope]) -> [UInt8] {
        var e = CanonicalEncoder()
        for b in magic { e.appendU8(b) }
        e.appendU16(formatVersion)
        e.appendBytes(salt)
        e.appendI64(createdAtUnixSeconds)
        e.appendU32(UInt32(entries.count))
        for env in entries { env.encode(into: &e) }
        return e.bytes
    }

    public var authenticatedBytes: [UInt8] {
        PortableBackup.authenticatedBytes(formatVersion: formatVersion, salt: salt, createdAtUnixSeconds: createdAtUnixSeconds, entries: entries)
    }

    /// Full serialized form: authenticated bytes followed by the length-prefixed tag.
    public func encode() -> [UInt8] {
        var e = CanonicalEncoder()
        for b in authenticatedBytes { e.appendU8(b) }
        e.appendBytes(integrityTag)
        return e.bytes
    }

    public static func decode(_ bytes: [UInt8]) throws -> PortableBackup {
        var d = CanonicalDecoder(bytes)
        for expected in magic {
            guard try d.readU8() == expected else { throw VaultError.backupCorrupted(reason: "bad magic") }
        }
        let v = try d.readU16()
        guard v == currentFormatVersion else { throw VaultError.unsupportedFormat(v) }
        let salt = try d.readBytes()
        let t = try d.readI64()
        let n = Int(try d.readU32())
        guard n <= 1_000_000 else { throw VaultError.backupCorrupted(reason: "entry count") }
        var entries: [RecordEnvelope] = []
        entries.reserveCapacity(n)
        for _ in 0..<n { entries.append(try RecordEnvelope.decode(from: &d)) }
        let tag = try d.readBytes()
        guard d.isAtEnd else { throw VaultError.backupCorrupted(reason: "trailing bytes") }
        return PortableBackup(formatVersion: v, salt: salt, createdAtUnixSeconds: t, entries: entries, integrityTag: tag)
    }
}

extension PortableBackup: CustomStringConvertible {
    public var description: String {
        "PortableBackup(v" + String(formatVersion) + ", entries: " + String(entries.count) + ", payload: <encrypted>)"
    }
}
